using System;using System.IO;using System.IO.Compression;using System.Diagnostics;using System.Collections.Generic;using System.Web.Script.Serialization;using System.Security.Cryptography;using System.Windows.Forms;using System.Threading;
class StarForgeUpdater {
 static JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=16000000};static string Root,Backup;static List<string> Applied=new List<string>(),Created=new List<string>();
 static HashSet<string> Core=new HashSet<string>(StringComparer.OrdinalIgnoreCase){"index.html","native.html","style.css","app.js","sample.js","dialogue.js","features.js","history-tools.js","group-tools.js","studio-tools.js","path-tools.js","music-library.js","remix-timeline.js","session-debug.js","native.js","native-motion.js","model-preview.js","models.json","version.json","changelog.json","StarForge.ico","StarForge.exe","StarForgeUpdater.exe","updates.json","Corneria.starlevel","Corneria.starstage.json","Meteo.starstage.json","Sector-X.starstage.json","Area-6.starstage.json","Sector-Y.starstage.json","Venom-1.starstage.json","Solar.starstage.json","Zoness.starstage.json"};
 static bool Allowed(string path){if(path.Contains(":")||path.StartsWith("/")||path.Split('/').ContainsDotDot())return false;return Core.Contains(path)||path.Equals("NativeGame/Starship.exe",StringComparison.OrdinalIgnoreCase)||path.Equals("NativeGame/config.yml",StringComparison.OrdinalIgnoreCase)||path.Equals("NativeGame/starship.o2r",StringComparison.OrdinalIgnoreCase)||path.Equals("NativeGame/gamecontrollerdb.txt",StringComparison.OrdinalIgnoreCase)||path.StartsWith("NativeGame/assets/",StringComparison.OrdinalIgnoreCase);}
 static string Safe(string root,string relative){if(relative.Contains(":")||relative.StartsWith("/")||relative.Split('/').ContainsDotDot())throw new Exception("Unsafe update path.");string path=Path.GetFullPath(Path.Combine(root,relative.Replace('/',Path.DirectorySeparatorChar)));if(!path.StartsWith(Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new Exception("Update escaped its destination.");return path;}
 static string Hash(string path){using(var sha=SHA256.Create())using(var stream=File.OpenRead(path))return BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","").ToLowerInvariant();}
 [STAThread]static int Main(string[] args){if(args.Length==2&&args[0]=="--verify-path"){try{Console.WriteLine(Allowed(args[1]));return Allowed(args[1])?0:2;}catch{return 3;}}try{if(args.Length!=1)throw new Exception("Missing update job.");var job=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(args[0]));Root=Path.GetFullPath(Convert.ToString(job["root"]));string archive=Convert.ToString(job["archive"]);if(Hash(archive)!=Convert.ToString(job["sha256"]))throw new Exception("Update archive checksum changed.");
  try{using(var host=Process.GetProcessById(Convert.ToInt32(job["hostPid"])))if(!host.WaitForExit(30000))throw new Exception("The launcher did not close. Close it and try again.");}catch(ArgumentException){}
  string staging=Path.Combine(Root,"Updates","staging-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(staging);Backup=Path.Combine(Root,"Updates","rollback-"+DateTime.Now.ToString("yyyyMMdd-HHmmss"));Directory.CreateDirectory(Backup);var files=new List<string>();
  using(var zip=ZipFile.OpenRead(archive)){foreach(var entry in zip.Entries){string full=entry.FullName.Replace('\\','/'),marker="/StarForge/";int at=full.IndexOf(marker,StringComparison.Ordinal);if(at<0||full.EndsWith("/"))continue;string relative=full.Substring(at+marker.Length);if(!Allowed(relative))continue;string destination=Safe(staging,relative);Directory.CreateDirectory(Path.GetDirectoryName(destination));entry.ExtractToFile(destination,true);files.Add(relative);}}
  if(!files.Contains("version.json")||!files.Contains("StarForge.exe"))throw new Exception("The update is missing required program files.");var version=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(staging,"version.json")));if(Convert.ToString(version["version"])!=Convert.ToString(job["version"]))throw new Exception("Update version mismatch.");
  foreach(string relative in files){string target=Safe(Root,relative),old=Safe(Backup,relative);if(File.Exists(target)){Directory.CreateDirectory(Path.GetDirectoryName(old));File.Copy(target,old,true);}else Created.Add(relative);Directory.CreateDirectory(Path.GetDirectoryName(target));string temp=target+".update-new";File.Copy(Safe(staging,relative),temp,true);if(File.Exists(target))File.Replace(temp,target,null);else File.Move(temp,target);Applied.Add(relative);}
  File.WriteAllText(Path.Combine(Root,"Updates","last-result.json"),Json.Serialize(new{success=true,version=job["version"]}));Process.Start(new ProcessStartInfo(Path.Combine(Root,"StarForge.exe")){WorkingDirectory=Root,UseShellExecute=true});return 0;
 }catch(Exception error){if(Root!=null){foreach(string relative in Applied){try{string old=Safe(Backup,relative),target=Safe(Root,relative);if(File.Exists(old))File.Copy(old,target,true);else if(Created.Contains(relative)&&File.Exists(target))File.Delete(target);}catch{} }try{File.WriteAllText(Path.Combine(Root,"Updates","last-result.json"),Json.Serialize(new{success=false,error=error.Message}));Process.Start(new ProcessStartInfo(Path.Combine(Root,"StarForge.exe")){WorkingDirectory=Root,UseShellExecute=true});}catch{} }MessageBox.Show("StarForge could not install the update. The previous version was restored where possible.\n\n"+error.Message,"StarForge update");return 1;}}
}
static class PathParts{public static bool ContainsDotDot(this string[] parts){foreach(string part in parts)if(part=="..")return true;return false;}}

